create type public.user_role as enum ('admin','student');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,email text not null,role public.user_role not null default 'student',created_at timestamptz default now());
create table public.courses(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',thumbnail_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.lessons(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,content text not null default '',lesson_order int not null default 1,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,course_id uuid not null references public.courses(id) on delete cascade,enrolled_at timestamptz default now(),unique(student_id,course_id));
create table public.lesson_progress(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,lesson_id uuid not null references public.lessons(id) on delete cascade,completed boolean not null default false,completed_at timestamptz,unique(student_id,lesson_id));
create index lessons_course_id_idx on public.lessons(course_id);create index enrollments_student_id_idx on public.enrollments(student_id);create index progress_student_id_idx on public.lesson_progress(student_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security;alter table public.courses enable row level security;alter table public.lessons enable row level security;alter table public.enrollments enable row level security;alter table public.lesson_progress enable row level security;
create policy "profiles own" on public.profiles for select using (id=auth.uid() or public.is_admin());create policy "profiles insert own" on public.profiles for insert with check(id=auth.uid() and role='student');create policy "profiles update own" on public.profiles for update using(id=auth.uid() or public.is_admin());
create policy "courses public read" on public.courses for select using(true);create policy "courses admin write" on public.courses for all using(public.is_admin()) with check(public.is_admin());
create policy "lessons enrolled read" on public.lessons for select using(public.is_admin() or exists(select 1 from public.enrollments e where e.course_id=course_id and e.student_id=auth.uid()));create policy "lessons admin write" on public.lessons for all using(public.is_admin()) with check(public.is_admin());
create policy "enroll own" on public.enrollments for select using(student_id=auth.uid() or public.is_admin());create policy "enroll insert own" on public.enrollments for insert with check(student_id=auth.uid());create policy "enroll admin" on public.enrollments for all using(public.is_admin()) with check(public.is_admin());
create policy "progress own" on public.lesson_progress for select using(student_id=auth.uid() or public.is_admin());create policy "progress insert own" on public.lesson_progress for insert with check(student_id=auth.uid());create policy "progress update own" on public.lesson_progress for update using(student_id=auth.uid() or public.is_admin()) with check(student_id=auth.uid() or public.is_admin());
